	if err := os.MkdirAll(filepath.Join(outputDir, seedDirName, seedDocsDirName), 0o700); err != nil {
		return err
	}
	if err := writeJSONFile(filepath.Join(outputDir, seedDirName, "file-index.json"), scan.Files); err != nil {
